SELECT Customer.FirstName, Customer.LastName, Employee.City
  FROM Customer
  JOIN Employee ON Customer.SupportRepId = Employee.EmployeeId;

SELECT e1.LastName AS EmployeeName, e2.FirstName AS ReportingEmployeeFirstName
  FROM Employee e1
  JOIN Employee e2 ON e1.ReportsTo = e2.EmployeeId;

SELECT Invoice.BillingCountry, SUM(Invoice.Total) as TotalInvoiceAmount
  FROM Invoice
  GROUP BY Invoice.BillingCountry;

SELECT Name FROM Artist
  LEFT JOIN Album ON Artist.ArtistId = Album.ArtistId
  WHERE Album.AlbumId IS NULL;
